// The app's third-party notices, generated by the build (issue #823): every package compiled into the main, preload and
// editor bundles, every package shipped as node_modules, the npm the app sets projects up with, the website starter's
// packages in the bundled npm cache, and the fonts of the bundled theme packs, each with its full licence text.
//
// - `bundledPackagesPlugin(target, file)`: a Vite plugin that writes the packages in one build's final chunks to `file`.
// - `build/after-pack.cjs` calls `buildNotices` with what ships for the platform and writes THIRD_PARTY_NOTICES.txt into
//   the app's resources, beside LICENSE.txt.
// - `node build/notices.cjs` writes .tmp/notices/THIRD_PARTY_NOTICES.txt for a development build (`npm run build`), which
//   Help > Third-Party Notices opens when the app is not packaged.
const { existsSync, mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } = require('node:fs');
const { dirname, isAbsolute, join, relative, resolve, sep } = require('node:path');

/**
 * File names that carry a licence, a copyright or a notice: LICENSE, LICENCE.md, COPYING, NOTICE, LICENSE-MIT,
 * THIRD-PARTY-LICENSE, ThirdPartyNotices.txt... Source files that only share the name (`bin/license.js`) are code, not text.
 */
const LICENCE_FILE = /^(licen[cs]e|copying|notice|copyright|third[-_]?party[-_]?(notices?|licen[cs]es?))([-_.][\w.-]*)?$/i;
const CODE_FILE = /\.(c|m)?(js|ts)x?$|\.d\.(c|m)?ts$|\.json$|\.map$/i;
const README_FILE = /^readme(\.(md|markdown|txt))?$/i;
/** How deep inside a package to look for vendored licences (`openai/src/internal/qs/LICENSE.md`). */
const MAX_DEPTH = 4;
const MAX_TEXT = 512 * 1024;

/** The parts of the app a package can ship in, in the order the file names them. */
const PARTS = {
  main: 'compiled into the app',
  preload: 'compiled into the app',
  renderer: 'compiled into the editor',
  shipped: 'shipped with the app',
  npm: 'npm, which sets projects up',
  starter: 'the website starter, cached for setting projects up offline'
};

/** The package root that owns a module id, or null when it is not under node_modules. Scoped and nested packages keep their own root. */
function packageRootOf(id) {
  const clean = String(id).replace(/^\0+/, '').replace(/[?#].*$/, '').split(sep).join('/');
  const at = clean.lastIndexOf('/node_modules/');
  if (at < 0) return null;
  const rest = clean.slice(at + '/node_modules/'.length).split('/');
  const name = rest[0]?.startsWith('@') ? (rest[1] ? `${rest[0]}/${rest[1]}` : null) : rest[0];
  if (!name || name.startsWith('.')) return null;
  return `${clean.slice(0, at)}/node_modules/${name}`;
}

function readJson(file) {
  return JSON.parse(readFileSync(file, 'utf8'));
}

/** A package.json `license` (an SPDX expression, an old `{ type }` object, or an old `licenses` list) as one string. */
function declaredLicence(pkg) {
  const one = (l) => (typeof l === 'string' ? l : l && typeof l.type === 'string' ? l.type : null);
  if (one(pkg.license)) return one(pkg.license);
  if (Array.isArray(pkg.licenses)) {
    const all = pkg.licenses.map(one).filter(Boolean);
    if (all.length) return all.length > 1 ? `(${all.join(' OR ')})` : all[0];
  }
  return 'UNKNOWN';
}

function repositoryOf(pkg) {
  const r = typeof pkg.repository === 'string' ? pkg.repository : pkg.repository?.url;
  return (r ?? pkg.homepage ?? '').replace(/^git\+/, '') || null;
}

function readText(file) {
  try {
    if (statSync(file).size > MAX_TEXT) return null;
    return readFileSync(file, 'utf8').replace(/\r\n?/g, '\n').trim();
  } catch {
    return null;
  }
}

/** Every licence file in a package, its own first, then vendored ones below it; nested packages are left to themselves. */
function licenceFiles(dir) {
  const out = [];
  const walk = (at, depth) => {
    let entries;
    try {
      entries = readdirSync(at, { withFileTypes: true }).sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
    } catch {
      return;
    }
    for (const e of entries) if (e.isFile() && LICENCE_FILE.test(e.name) && !CODE_FILE.test(e.name)) out.push(join(at, e.name));
    if (depth >= MAX_DEPTH) return;
    for (const e of entries) {
      if (!e.isDirectory() || e.name === 'node_modules' || e.name.startsWith('.')) continue;
      // A folder with its own package.json and a name is a package of its own.
      const manifest = join(at, e.name, 'package.json');
      if (existsSync(manifest)) {
        try {
          if (readJson(manifest).name) continue;
        } catch {
          // Not a manifest we can read: look inside anyway.
        }
      }
      walk(join(at, e.name), depth + 1);
    }
  };
  walk(dir, 0);
  return out;
}

/**
 * The Licence section of a package's README, for a package that ships no licence file. `complete` says whether it names
 * a copyright holder or grants the licence itself, rather than only naming one (`## License\n\nMIT`).
 */
function readmeLicence(dir) {
  let names;
  try {
    names = readdirSync(dir).filter((n) => README_FILE.test(n)).sort();
  } catch {
    return null;
  }
  for (const n of names) {
    const text = readText(join(dir, n));
    if (!text) continue;
    const lines = text.split('\n');
    const start = lines.findIndex((l) => /^#{1,6}\s+licen[cs](e|ing)\b/i.test(l));
    if (start < 0) continue;
    const level = lines[start].match(/^#+/)[0].length;
    let end = lines.findIndex((l, i) => i > start && /^#{1,6}\s/.test(l) && l.match(/^#+/)[0].length <= level);
    if (end < 0) end = lines.length;
    const section = lines.slice(start, end).join('\n').trim();
    // Links do not count: a URL such as .../COPYRIGHT names a file, it holds no notice.
    const prose = section.replace(/\]\([^)]*\)/g, ']').replace(/https?:\/\/\S+/g, '');
    if (section.split('\n').length > 1) return { file: n, text: section, complete: /\bcopyright\b|permission is hereby granted|licensed under/i.test(prose) };
  }
  return null;
}

/**
 * A package's notice: name, version, declared licence, repository, and the full text of every licence file it carries.
 * With none, the file `SEE LICENSE IN` names, then its README's Licence section; `missing` says when neither was there.
 */
function readPackage(dir) {
  const pkg = readJson(join(dir, 'package.json'));
  const licence = declaredLicence(pkg);
  const texts = [];
  for (const f of licenceFiles(dir)) {
    const text = readText(f);
    if (text) texts.push({ file: relative(dir, f).split(sep).join('/'), text });
  }
  let missing = false;
  if (!texts.length) {
    const named = /^SEE LICEN[CS]E IN (.+)$/i.exec(licence)?.[1]?.trim();
    const text = named ? readText(join(dir, named)) : null;
    if (text) texts.push({ file: named, text });
    else {
      const readme = readmeLicence(dir);
      if (readme) texts.push({ file: readme.file, text: readme.text });
      missing = !readme?.complete;
    }
  }
  return { name: pkg.name ?? dir.split(sep).pop(), version: pkg.version ?? '0.0.0', licence, repository: repositoryOf(pkg), texts, missing };
}

/** Every package installed under a node_modules folder, nested ones too. */
function packagesUnder(nodeModules) {
  const out = [];
  const visit = (nm) => {
    let names;
    try {
      names = readdirSync(nm).sort();
    } catch {
      return;
    }
    for (const n of names) {
      if (n.startsWith('.')) continue;
      const dirs = n.startsWith('@') ? (() => { try { return readdirSync(join(nm, n)).sort().map((s) => join(nm, n, s)); } catch { return []; } })() : [join(nm, n)];
      for (const d of dirs) {
        if (!existsSync(join(d, 'package.json'))) continue;
        out.push(d);
        visit(join(d, 'node_modules'));
      }
    }
  };
  visit(nodeModules);
  return out;
}

/** The folder of package `name` as Node would find it from `from`: the nearest node_modules/<name> up the tree. */
function findInstalled(name, from) {
  for (let at = resolve(from); ; at = dirname(at)) {
    const dir = join(at, 'node_modules', ...name.split('/'));
    if (existsSync(join(dir, 'package.json'))) return dir;
    if (dirname(at) === at) return null;
  }
}

/** The licence of the helpers Rolldown inlines from `@oxc-project/runtime`, which it resolves without installing the package. */
const OXC_RUNTIME_LICENCE = join(__dirname, 'licences', 'oxc-project-runtime.LICENSE');

/**
 * Code a bundler writes into the output from a virtual module, with no node_modules path to name it: Rolldown's
 * runtime (`\0rolldown/runtime.js`), Vite's helpers (`\0vite/preload-helper.js`) and the Babel-derived helpers of
 * `@oxc-project/runtime` (`\0@oxc-project+runtime@0.156.0/helpers/...`). Each gives the package it comes from.
 */
function virtualProvider(id, root) {
  const clean = String(id).replace(/^\0+/, '');
  const oxc = /^@oxc-project\+runtime@([^/]+)\//.exec(clean);
  if (oxc) {
    const text = readFileSync(OXC_RUNTIME_LICENCE, 'utf8').replace(/\r\n?/g, '\n').trim();
    return { notice: { name: '@oxc-project/runtime', version: oxc[1], licence: 'MIT', repository: 'https://github.com/oxc-project/oxc', texts: [{ file: 'LICENSE', text }], missing: false } };
  }
  const vite = findInstalled('vite', root);
  if (/^vite\//.test(clean)) return vite ? { dir: vite } : null;
  if (/^rolldown\//.test(clean)) {
    const rolldown = findInstalled('rolldown', vite ?? root);
    return rolldown ? { dir: rolldown } : null;
  }
  return null;
}

/**
 * A Vite plugin that records the packages whose code is in one build's final chunks and assets, as
 * `{ target, packages: [{ name, version, dir } | { name, version, notice }] }` in `file`: modules under node_modules,
 * and the bundler's own helpers (virtualProvider). A production build only; the dev server writes nothing.
 */
function bundledPackagesPlugin(target, file) {
  let roots = new Set();
  let virtual = new Map();
  let base = process.cwd();
  return {
    name: 'siteorigin-bundled-packages',
    apply: 'build',
    configResolved(config) {
      // Asset names are relative to the build's root (src/renderer for the editor).
      base = config.root ?? base;
    },
    buildStart() {
      roots = new Set();
      virtual = new Map();
    },
    generateBundle(_options, bundle) {
      for (const out of Object.values(bundle)) {
        const ids = out.type === 'chunk' ? (out.moduleIds ?? Object.keys(out.modules ?? {})) : [...(out.originalFileNames ?? [])].map((n) => (isAbsolute(n) ? n : resolve(base, n)));
        for (const id of ids) {
          const root = packageRootOf(id);
          if (root) {
            if (existsSync(join(root, 'package.json'))) roots.add(root);
            continue;
          }
          const provider = virtualProvider(id, base);
          if (provider?.dir) roots.add(provider.dir);
          else if (provider?.notice) virtual.set(`${provider.notice.name}@${provider.notice.version}`, provider.notice);
        }
      }
    },
    writeBundle() {
      const packages = [
        ...[...roots].map((dir) => {
          const pkg = readJson(join(dir, 'package.json'));
          return { name: pkg.name, version: pkg.version, dir: resolve(dir) };
        }),
        ...[...virtual.values()].map((notice) => ({ name: notice.name, version: notice.version, notice }))
      ]
        .sort((a, b) => compare(a.name, b.name) || compare(a.version, b.version));
      mkdirSync(dirname(file), { recursive: true });
      writeFileSync(file, `${JSON.stringify({ target, packages }, null, 2)}\n`);
    }
  };
}

function compare(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

/** The fonts of the theme packs in `packsDirs`, one entry per family and notice, with the packs that ship it. */
function packFonts(packsDirs) {
  const fonts = new Map();
  for (const packs of packsDirs) {
    let ids;
    try {
      ids = readdirSync(packs).filter((n) => !n.startsWith('.')).sort();
    } catch {
      continue;
    }
    for (const id of ids) {
      const manifest = join(packs, id, 'pack.json');
      if (!existsSync(manifest)) continue;
      const pack = readJson(manifest);
      for (const f of pack.fonts ?? []) {
        const notice = String(f.notice ?? '').replace(/\r\n?/g, '\n').trim();
        const key = `${f.family}\n${notice}`;
        const entry = fonts.get(key) ?? { name: f.name, family: f.family, licence: f.license, notice, packs: new Set() };
        entry.packs.add(pack.name ?? id);
        fonts.set(key, entry);
      }
    }
  }
  return [...fonts.values()].sort((a, b) => compare(a.name, b.name) || compare(a.family, b.family)).map((f) => ({ ...f, packs: [...f.packs].sort() }));
}

/** The bundles' packages, from the manifests the Vite plugin wrote. Every target must have built. */
function bundledPackages(manifestDir, targets = ['main', 'preload', 'renderer']) {
  const out = {};
  for (const t of targets) {
    const file = join(manifestDir, `${t}.json`);
    if (!existsSync(file)) throw new Error(`${file} is missing: run electron-vite build before packaging, so the notices can list what the ${t} bundle contains.`);
    out[t] = readJson(file).packages.map((p) => p.notice ?? p.dir);
  }
  return out;
}

const RULE = '='.repeat(78);

/**
 * The notices file. `packages` is a list of `{ pkg, parts }` (a `readPackage` result and the PARTS keys it ships in);
 * one package version is listed once, whatever ships it. Sorted by name and version, so the same inputs make the same file.
 */
function renderNotices({ packages, fonts }) {
  const merged = new Map();
  for (const { pkg, parts } of packages) {
    const key = `${pkg.name}@${pkg.version}`;
    const entry = merged.get(key) ?? { pkg: { ...pkg, texts: [] }, parts: new Set() };
    for (const p of parts) entry.parts.add(PARTS[p] ?? p);
    // Two copies of one version can carry different notices: every distinct text is kept.
    for (const t of pkg.texts) if (!entry.pkg.texts.some((u) => u.file === t.file && u.text === t.text)) entry.pkg.texts.push(t);
    entry.pkg.missing = entry.pkg.texts.length ? entry.pkg.missing && pkg.missing : true;
    merged.set(key, entry);
  }
  const list = [...merged.values()].sort((a, b) => compare(a.pkg.name, b.pkg.name) || compare(a.pkg.version, b.pkg.version));
  const lines = [
    'SiteOrigin Builder: third-party notices',
    '',
    'SiteOrigin Builder is licensed under the Apache License, Version 2.0: see LICENSE.txt beside this file.',
    'It includes the software and fonts below, each under its own licence, whose notices follow in full.',
    "Electron's and Chromium's licences ship with the app as LICENSE.electron.txt and LICENSES.chromium.html.",
    '',
    `Packages: ${list.length}. Font families: ${fonts.length}.`,
    ''
  ];
  for (const { pkg, parts } of list) {
    lines.push(RULE, `${pkg.name} ${pkg.version}`, `Licence: ${pkg.licence}`);
    if (pkg.repository) lines.push(`Source: ${pkg.repository}`);
    lines.push(`Included in: ${[...parts].sort().join('; ')}`, '');
    if (pkg.missing) lines.push(pkg.texts.length ? 'The package carries no licence file; its README’s licence section follows, with the declared licence above.' : 'The package carries no licence text; its declared licence is above.', '');
    for (const t of pkg.texts) lines.push(`--- ${t.file} ---`, '', t.text, '');
  }
  for (const f of fonts) {
    lines.push(RULE, `Font: ${f.name} (${f.family})`, `Licence: ${f.licence}`, `Included in theme packs: ${f.packs.join(', ')}`, '', f.notice, '');
  }
  return `${lines.join('\n').trimEnd()}\n`;
}

/**
 * Read every package `parts` names (`{ part: [package folder or readPackage result] }`) and the fonts in `packsDirs`,
 * and render the file. `missing` lists the packages that carry no licence text, for the build to warn about.
 */
function buildNotices({ parts, packsDirs = [] }) {
  const packages = [];
  const seen = new Map();
  for (const [part, items] of Object.entries(parts)) {
    for (const item of items) {
      if (typeof item !== 'string') {
        packages.push({ pkg: item, parts: [part] });
        continue;
      }
      const key = resolve(item);
      if (!seen.has(key)) seen.set(key, readPackage(item));
      packages.push({ pkg: seen.get(key), parts: [part] });
    }
  }
  const missing = [...new Set(packages.filter((p) => p.pkg.missing).map((p) => `${p.pkg.name}@${p.pkg.version} (${p.pkg.licence})`))].sort();
  return { text: renderNotices({ packages, fonts: packFonts(packsDirs) }), missing };
}

/** The production packages installed under `root`, as package-lock.json records them (no development-only ones). */
function productionPackages(root) {
  const lock = readJson(join(root, 'package-lock.json'));
  return Object.entries(lock.packages ?? {})
    .filter(([path, p]) => path.startsWith('node_modules/') && !p.dev && !p.devOptional && !p.link)
    .map(([path]) => join(root, path))
    .filter((dir) => existsSync(join(dir, 'package.json')))
    .sort();
}

const NOTICES_FILE = 'THIRD_PARTY_NOTICES.txt';

function warnMissing(missing, log = console.warn) {
  if (missing.length) log(`Third-party notices: ${missing.length} package(s) carry no licence text, so only their declared licence is listed:\n  ${missing.join('\n  ')}`);
}

module.exports = { LICENCE_FILE, CODE_FILE, NOTICES_FILE, findInstalled, virtualProvider, PARTS, packageRootOf, declaredLicence, readPackage, licenceFiles, readmeLicence, packagesUnder, bundledPackagesPlugin, bundledPackages, packFonts, renderNotices, buildNotices, productionPackages, warnMissing };

// `node build/notices.cjs`: the development build's notices, from the bundles just built and the installed packages.
if (require.main === module) {
  const root = resolve(__dirname, '..');
  const manifestDir = join(root, '.tmp', 'notices');
  const { text, missing } = buildNotices({
    parts: { ...bundledPackages(manifestDir), shipped: productionPackages(root), npm: [join(root, 'node_modules', 'npm'), ...packagesUnder(join(root, 'node_modules', 'npm', 'node_modules'))] },
    packsDirs: [join(root, 'resources', 'packs'), join(root, 'resources', 'packs-dev')]
  });
  writeFileSync(join(manifestDir, NOTICES_FILE), text);
  warnMissing(missing);
  console.log(`Third-party notices written to ${relative(root, join(manifestDir, NOTICES_FILE))} (${(text.length / 1024).toFixed(0)} KB).`);
}
